import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to approximate specific ELA features.
    """
    n = len(x)
    quad_term = 0.0
    for i in range(n):
        for j in range(i + 1, n):
             quad_term += 0.01 * x[i] * x[j]

    result = np.sum(x**2) + quad_term + 0.1 * np.sin(x[0])
    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to approximate specific ELA features.
    """
    n = len(x)
    result = 0.0
    for i in range(n):
        result += np.exp(0.1 * x[i]**4)

    quad_term = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            quad_term += 0.005 * x[i] * x[j]

    skew_term = 1.0 / (1.0 + np.exp(-0.2 * x[0]))

    return float(result + quad_term + 0.05 * skew_term)

